{
  "name": "pi-model-switch",
  "version": "0.3.0",
  "description": "Model switching extension for pi coding agent",
  "type": "module",
  "files": [
    "CHANGELOG.md",
    "README.md",
    "index.ts"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "test": "tsx --test test/*.test.ts"
  },
  "peerDependencies": {
    "@earendil-works/pi-ai": "*",
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "devDependencies": {
    "@earendil-works/pi-ai": "0.87.1",
    "@earendil-works/pi-coding-agent": "0.87.1",
    "@types/node": "22.20.4",
    "tsx": "4.23.15",
    "typebox": "1.3.34",
    "typescript": "5.9.3"
  },
  "keywords": [
    "pi-package",
    "pi",
    "pi-coding-agent",
    "extension",
    "model",
    "switch",
    "llm"
  ],
  "license": "MIT",
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  }
}

import assert from "node:assert/strict";
import { mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import type { ExtensionAPI, ExtensionContext, ToolDefinition } from "@earendil-works/pi-coding-agent";
import extension from "../index.ts";

const primaryModel = {
	provider: "provider-a",
	id: "model-a",
	name: "Model A",
	reasoning: false,
	input: ["text"] as const,
	contextWindow: 128_000,
	maxTokens: 8_192,
	cost: { input: 1, output: 2, cacheRead: 0.1, cacheWrite: 1.25 },
};

const secondaryModel = {
	...primaryModel,
	provider: "provider-b",
	id: "model-b",
	name: "Model B",
};

type ThinkingLevel = Parameters<ExtensionAPI["setThinkingLevel"]>[0];
type SetupOptions = {
	setModel?: ExtensionAPI["setModel"];
	setThinkingLevel?: (level: ThinkingLevel) => void;
	getThinkingLevel?: () => ThinkingLevel;
	handlers?: Map<string, (event: unknown, ctx: ExtensionContext) => void>;
};

function setupTool(options: SetupOptions = {}): ToolDefinition {
	let registered: ToolDefinition | undefined;
	extension({
		on(event: string, handler: (event: unknown, ctx: ExtensionContext) => void) {
			options.handlers?.set(event, handler);
		},
		registerTool(tool: ToolDefinition) {
			registered = tool;
		},
		setModel: options.setModel ?? (async () => true),
		setThinkingLevel: options.setThinkingLevel ?? (() => {}),
		getThinkingLevel: options.getThinkingLevel ?? (() => "medium"),
	} as unknown as ExtensionAPI);
	assert.ok(registered);
	return registered;
}

function context({
	currentModel = primaryModel as typeof primaryModel | null,
	models = [primaryModel, secondaryModel],
	cwd = process.cwd(),
	branch = [] as unknown[],
	status = new Map<string, string | undefined>(),
}: {
	currentModel?: typeof primaryModel | null;
	models?: typeof primaryModel[];
	cwd?: string;
	branch?: unknown[];
	status?: Map<string, string | undefined>;
} = {}): ExtensionContext {
	return {
		cwd,
		model: currentModel,
		modelRegistry: { getAvailable: () => models },
		sessionManager: { getBranch: () => branch },
		getContextUsage: () => ({ tokens: 100_000, contextWindow: 128_000, percent: 78 }),
		ui: { setStatus: (key: string, text: string | undefined) => status.set(key, text) },
	} as unknown as ExtensionContext;
}

async function aliasCwd(t: test.TestContext, aliases: unknown): Promise<string> {
	const cwd = join(tmpdir(), `pi-model-switch-${process.pid}-${Date.now()}-${Math.random()}`);
	await mkdir(join(cwd, ".pi"), { recursive: true });
	await writeFile(join(cwd, ".pi", "aliases.json"), JSON.stringify(aliases));
	t.after(() => rm(cwd, { recursive: true, force: true }));
	return cwd;
}

function text(result: Awaited<ReturnType<ToolDefinition["execute"]>>): string {
	const content = result.content[0];
	assert.equal(content?.type, "text");
	return content.text;
}

test("publishes provider-compatible action and thinking-level enums", () => {
	const tool = setupTool();
	const properties = (tool.parameters as unknown as {
		properties: Record<string, { enum?: string[]; anyOf?: unknown }>;
	}).properties;

	assert.deepEqual(properties.action.enum, ["current", "list", "search", "switch"]);
	assert.equal(properties.action.anyOf, undefined);
	assert.deepEqual(properties.thinkingLevel.enum, ["minimal", "low", "medium", "high", "xhigh", "max"]);
	assert.equal(properties.thinkingLevel.anyOf, undefined);
});

test("current reports the model and effective thinking level, or throws without a model", async () => {
	const tool = setupTool({ getThinkingLevel: () => "high" });
	const result = await tool.execute("call-current", { action: "current" }, undefined, undefined, context());

	assert.match(text(result), /Current model: provider-a\/model-a \(Model A\), thinking: high/);
	assert.equal(result.details, undefined);
	await assert.rejects(
		tool.execute("call-no-current", { action: "current" }, undefined, undefined, context({ currentModel: null })),
		/No model is currently active/,
	);
});

test("requires a search argument for switching", async () => {
	const tool = setupTool();
	await assert.rejects(
		tool.execute("call-missing", { action: "switch" }, undefined, undefined, context()),
		/search parameter required for switch action/,
	);
});

test("direct switching preserves omitted-level behavior and applies an explicit level after setModel", async () => {
	const calls: string[] = [];
	const tool = setupTool({
		setModel: async (model) => {
			calls.push(`model:${model.id}`);
			return true;
		},
		setThinkingLevel: (level) => calls.push(`thinking:${level}`),
		getThinkingLevel: () => "high",
	});
	const omitted = await tool.execute(
		"call-omitted",
		{ action: "switch", search: "provider-b/model-b" },
		undefined,
		undefined,
		context(),
	);
	assert.deepEqual(calls, ["model:model-b"]);
	assert.match(text(omitted), /^Switched to provider-b\/model-b \(Model B\)$/);
	assert.equal(omitted.details, undefined);

	calls.length = 0;
	const explicit = await tool.execute(
		"call-explicit",
		{ action: "switch", search: "provider-b/model-b", thinkingLevel: "high" },
		undefined,
		undefined,
		context(),
	);
	assert.deepEqual(calls, ["model:model-b", "thinking:high"]);
	assert.match(text(explicit), /Switched to provider-b\/model-b .*thinking: high$/);
	assert.doesNotMatch(text(explicit), /requested/);
	assert.equal(explicit.details, undefined);
});

test("same-model requests skip setModel and only set thinking when requested", async () => {
	let modelCalls = 0;
	const levels: ThinkingLevel[] = [];
	const tool = setupTool({
		setModel: async () => {
			modelCalls += 1;
			return true;
		},
		setThinkingLevel: (level) => levels.push(level),
		getThinkingLevel: () => "low",
	});
	const omitted = await tool.execute(
		"call-same-omitted",
		{ action: "switch", search: "provider-a/model-a" },
		undefined,
		undefined,
		context(),
	);
	const changed = await tool.execute(
		"call-same-level",
		{ action: "switch", search: "provider-a/model-a", thinkingLevel: "low" },
		undefined,
		undefined,
		context(),
	);

	assert.equal(modelCalls, 0);
	assert.deepEqual(levels, ["low"]);
	assert.equal(text(omitted), "Already using provider-a/model-a");
	assert.match(text(changed), /^Already using provider-a\/model-a, thinking: low$/);
	assert.equal(omitted.details, undefined);
	assert.equal(changed.details, undefined);
});

test("warns about re-billing only when leaving a warm cache for a cold one", async () => {
	const assistantAt = (model: typeof primaryModel, ageMs: number) => ({
		type: "message",
		message: {
			role: "assistant",
			provider: model.provider,
			model: model.id,
			timestamp: Date.now() - ageMs,
			usage: { cacheRead: 90_000, cacheWrite: 10_000 },
		},
	});
	const handlers = new Map<string, (event: unknown, ctx: ExtensionContext) => void>();
	const tool = setupTool({ handlers });
	const status = new Map<string, string | undefined>();
	const warm = context({ branch: [assistantAt(primaryModel, 60_000)], status });
	const onSelect = handlers.get("model_select");
	assert.ok(onSelect);

	onSelect({ type: "model_select", model: secondaryModel, previousModel: primaryModel, source: "cycle" }, warm);
	const [key, warning] = [...status.entries()][0] ?? [];
	assert.match(warning ?? "", /re-bills ~100k cached tokens .*provider-b\/model-b/);

	// Cycling back to the still-warm model clears the warning.
	const bothWarm = context({ branch: [assistantAt(primaryModel, 60_000), assistantAt(secondaryModel, 1_000)], status });
	onSelect({ type: "model_select", model: primaryModel, previousModel: secondaryModel, source: "cycle" }, bothWarm);
	assert.equal(status.get(key!), undefined);

	const warmSwitch = await tool.execute("call-warm", { action: "switch", search: "provider-b/model-b" }, undefined, undefined, warm);
	assert.match(text(warmSwitch), /\n\nNote: next request re-bills ~100k cached tokens/);
	const cold = context({ branch: [assistantAt(primaryModel, 10 * 60_000)] });
	const coldSwitch = await tool.execute("call-cold", { action: "switch", search: "provider-b/model-b" }, undefined, undefined, cold);
	assert.equal(text(coldSwitch), "Switched to provider-b/model-b (Model B)");
});

test("reports requested thinking only when Pi clamps it", async () => {
	const tool = setupTool({ getThinkingLevel: () => "high" });
	const result = await tool.execute(
		"call-clamped",
		{ action: "switch", search: "provider-b/model-b", thinkingLevel: "max" },
		undefined,
		undefined,
		context(),
	);

	assert.match(text(result), /thinking: high \(requested max\)$/);
	assert.equal(result.details, undefined);
});

test("propagates model and thinking setter failures", async () => {
	const rejectedModel = setupTool({ setModel: async () => false });
	await assert.rejects(
		rejectedModel.execute(
			"call-model-failure",
			{ action: "switch", search: "provider-b/model-b" },
			undefined,
			undefined,
			context(),
		),
		/Failed to switch to provider-b\/model-b/,
	);

	const rejectedThinking = setupTool({
		setThinkingLevel: () => {
			throw new Error("thinking setter failed");
		},
	});
	await assert.rejects(
		rejectedThinking.execute(
			"call-thinking-failure",
			{ action: "switch", search: "provider-a/model-a", thinkingLevel: "high" },
			undefined,
			undefined,
			context(),
		),
		/thinking setter failed/,
	);
});

test("supports legacy string aliases", async (t) => {
	const cwd = await aliasCwd(t, { legacy: "provider-b/model-b" });
	const tool = setupTool();
	const result = await tool.execute(
		"call-legacy",
		{ action: "switch", search: "legacy" },
		undefined,
		undefined,
		context({ cwd }),
	);

	assert.match(text(result), /Switched to provider-b\/model-b .*via alias "legacy"$/);
	assert.equal(result.details, undefined);
});

test("uses object alias thinking and lets an explicit level override it", async (t) => {
	const cwd = await aliasCwd(t, { coding: { model: "provider-b/model-b", thinkingLevel: "low" } });
	const levels: ThinkingLevel[] = [];
	let modelCalls = 0;
	const tool = setupTool({
		setModel: async () => {
			modelCalls += 1;
			return true;
		},
		setThinkingLevel: (level) => levels.push(level),
		getThinkingLevel: () => levels.at(-1) ?? "medium",
	});
	const configured = await tool.execute(
		"call-configured",
		{ action: "switch", search: "coding" },
		undefined,
		undefined,
		context({ cwd }),
	);
	const overridden = await tool.execute(
		"call-overridden",
		{ action: "switch", search: "coding", thinkingLevel: "max" },
		undefined,
		undefined,
		context({ currentModel: secondaryModel, cwd }),
	);

	assert.equal(modelCalls, 1);
	assert.deepEqual(levels, ["low", "max"]);
	assert.match(text(configured), /thinking: low$/);
	assert.match(text(overridden), /^Already using provider-b\/model-b via alias "coding", thinking: max$/);
	assert.equal(configured.details, undefined);
	assert.equal(overridden.details, undefined);
});

test("mixed alias fallbacks skip unavailable and setModel(false) candidates", async (t) => {
	const cwd = await aliasCwd(t, {
		fallback: [
			"missing/model",
			{ model: "provider-a/model-a", thinkingLevel: "low" },
			"provider-b/model-b",
		],
	});
	const attempted: string[] = [];
	const tool = setupTool({
		setModel: async (model) => {
			attempted.push(model.id);
			return model.id === "model-b";
		},
	});
	const result = await tool.execute(
		"call-fallback",
		{ action: "switch", search: "fallback" },
		undefined,
		undefined,
		context({ currentModel: null, cwd }),
	);

	assert.deepEqual(attempted, ["model-a", "model-b"]);
	assert.match(text(result), /Switched to provider-b\/model-b/);
	assert.equal(result.details, undefined);
});

test("invalid alias config follows the warning/error flow", async (t) => {
	const cwd = await aliasCwd(t, { broken: { model: "provider-b/model-b", thinkingLevel: "turbo" } });
	const tool = setupTool();

	await assert.rejects(
		tool.execute(
			"call-invalid-alias",
			{ action: "switch", search: "broken" },
			undefined,
			undefined,
			context({ cwd }),
		),
		/Warning: Failed to load .*alias "broken" has an invalid target or thinkingLevel/,
	);
});

test("exhausted alias fallback throws and lists every attempted spec", async (t) => {
	const cwd = await aliasCwd(t, {
		fallback: ["missing/model", { model: "provider-b/model-b", thinkingLevel: "high" }],
	});
	const tool = setupTool({ setModel: async () => false });

	await assert.rejects(
		tool.execute(
			"call-exhausted",
			{ action: "switch", search: "fallback" },
			undefined,
			undefined,
			context({ cwd }),
		),
		/No available models found for alias "fallback"\. Tried: missing\/model, provider-b\/model-b/,
	);
});

import type { ExtensionContext, ExtensionFactory } from "@earendil-works/pi-coding-agent";
import { StringEnum, type Api, type Model, type ThinkingLevel } from "@earendil-works/pi-ai";
import { Type } from "typebox";
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

type AliasTarget = {
	model: string;
	thinkingLevel?: ThinkingLevel;
};

type AliasConfig = Record<string, AliasTarget | AliasTarget[]>;

const THINKING_LEVELS = ["minimal", "low", "medium", "high", "xhigh", "max"] as const;
const CACHE_STATUS_KEY = "model-switch-cache";

function cacheTtlMs(model: Model<Api>): number {
	const retention = process.env.PI_CACHE_RETENTION === "long" ? "long" : "short";
	return (model.promptCache?.[retention] ?? 300) * 1000;
}

/**
 * Warns when leaving a model whose prompt cache is still warm. The switch itself
 * is free; the next request re-bills the whole prompt on the new model. Uses the
 * same thresholds as pi's after-the-fact "Cache miss after model switch" notice.
 */
function cacheSwitchWarning(ctx: ExtensionContext, from: Model<Api>, to: Model<Api>): string | undefined {
	const lastRequestAt = new Map<string, number>();
	for (const entry of ctx.sessionManager.getBranch()) {
		if (entry.type === "compaction" || entry.type === "branch_summary") {
			lastRequestAt.clear();
		} else if (entry.type === "message" && entry.message.role === "assistant") {
			// Providers that never report cache activity have nothing to lose.
			if (entry.message.usage.cacheRead + entry.message.usage.cacheWrite === 0) {
				continue;
			}
			lastRequestAt.set(`${entry.message.provider}/${entry.message.model}`, entry.message.timestamp);
		} else if (entry.type === "usage" && entry.kind === "cache_warm") {
			lastRequestAt.set(`${entry.provider}/${entry.model}`, Date.parse(entry.timestamp));
		}
	}

	const now = Date.now();
	const isWarm = (model: Model<Api>) =>
		now - (lastRequestAt.get(`${model.provider}/${model.id}`) ?? -Infinity) < cacheTtlMs(model);
	// Switching back to a model whose cache is still warm re-bills nothing already cached.
	if (!isWarm(from) || isWarm(to)) {
		return undefined;
	}

	const tokens = ctx.getContextUsage()?.tokens;
	if (!tokens) {
		return undefined;
	}
	const paidRate = to.cost.cacheWrite || to.cost.input;
	const cost = (tokens * Math.max(0, paidRate - to.cost.cacheRead)) / 1_000_000;
	if (tokens < 20_000 && cost < 0.1) {
		return undefined;
	}
	const costText = cost >= 0.01 ? ` (~$${cost.toFixed(2)})` : "";
	return `next request re-bills ~${Math.round(tokens / 1000)}k cached tokens${costText} on ${to.provider}/${to.id}`;
}

function parseModelSpec(spec: string): { provider: string; modelId: string } | null {
	const normalized = spec.trim();
	const slashIndex = normalized.indexOf("/");
	if (slashIndex <= 0 || slashIndex >= normalized.length - 1) {
		return null;
	}

	const provider = normalized.slice(0, slashIndex).trim();
	const modelId = normalized.slice(slashIndex + 1).trim();
	if (!provider || !modelId) {
		return null;
	}

	return { provider, modelId };
}

function parseAliasTarget(rawTarget: unknown): AliasTarget | null {
	if (typeof rawTarget === "string") {
		const model = rawTarget.trim();
		return model && parseModelSpec(model) ? { model } : null;
	}
	if (typeof rawTarget !== "object" || rawTarget === null || Array.isArray(rawTarget)) {
		return null;
	}

	if (!("model" in rawTarget) || typeof rawTarget.model !== "string") {
		return null;
	}
	const model = rawTarget.model.trim();
	if (!model || !parseModelSpec(model)) {
		return null;
	}
	const rawThinkingLevel = "thinkingLevel" in rawTarget ? rawTarget.thinkingLevel : undefined;
	const thinkingLevel = THINKING_LEVELS.find((level) => level === rawThinkingLevel);
	if (rawThinkingLevel !== undefined && thinkingLevel === undefined) {
		return null;
	}

	return {
		model,
		...(thinkingLevel !== undefined ? { thinkingLevel } : {}),
	};
}

function loadAliases(cwd: string, extensionDir: string): { aliases: AliasConfig; source?: string; error?: string } {
	const aliasPaths = [
		join(cwd, ".pi", "aliases.json"),
		join(homedir(), ".pi", "agent", "aliases.json"),
		join(extensionDir, "aliases.json"),
	];

	for (const aliasPath of aliasPaths) {
		if (!existsSync(aliasPath)) {
			continue;
		}

		try {
			const content = readFileSync(aliasPath, "utf-8");
			const parsed = JSON.parse(content);
			if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
				return { aliases: {}, error: `Failed to load ${aliasPath}: expected a top-level object of alias -> target|target[]` };
			}

			const aliases: AliasConfig = {};
			for (const [rawKey, rawValue] of Object.entries(parsed)) {
				const key = rawKey.trim();
				if (!key) {
					return { aliases: {}, error: `Failed to load ${aliasPath}: alias names must be non-empty strings` };
				}

				if (!Array.isArray(rawValue)) {
					const target = parseAliasTarget(rawValue);
					if (!target) {
						return { aliases: {}, error: `Failed to load ${aliasPath}: alias "${key}" has an invalid target or thinkingLevel` };
					}
					aliases[key] = target;
					continue;
				}

				if (rawValue.length === 0) {
					return { aliases: {}, error: `Failed to load ${aliasPath}: alias "${key}" must have at least one target` };
				}

				const values: AliasTarget[] = [];
				for (const candidate of rawValue) {
					const target = parseAliasTarget(candidate);
					if (!target) {
						return { aliases: {}, error: `Failed to load ${aliasPath}: alias "${key}" contains an invalid target or thinkingLevel` };
					}
					if (!values.some((value) => value.model === target.model && value.thinkingLevel === target.thinkingLevel)) {
						values.push(target);
					}
				}

				aliases[key] = values;
			}

			return { aliases, source: aliasPath };
		} catch (error) {
			return { aliases: {}, error: `Failed to load ${aliasPath}: ${error instanceof Error ? error.message : String(error)}` };
		}
	}

	return { aliases: {} };
}

function formatModelLine(
	model: {
		provider: string;
		id: string;
		name: string;
		reasoning: boolean;
		input: readonly string[];
		contextWindow: number;
		maxTokens: number;
		cost: { input: number; output: number };
	},
	currentModel: { provider?: string; id?: string } | null | undefined,
): string {
	const current = currentModel && model.provider === currentModel.provider && model.id === currentModel.id;
	const marker = current ? " (current)" : "";
	const capabilities = [model.reasoning ? "reasoning" : null, model.input.includes("image") ? "vision" : null]
		.filter(Boolean)
		.join(", ");
	const capabilityText = capabilities ? ` [${capabilities}]` : "";
	const costText = `$${model.cost.input.toFixed(2)}/$${model.cost.output.toFixed(2)} per 1M tokens (in/out)`;
	return `${model.provider}/${model.id}${marker}${capabilityText}\n  ${model.name} | ctx: ${model.contextWindow.toLocaleString()} | max: ${model.maxTokens.toLocaleString()}\n  ${costText}`;
}

const extension: ExtensionFactory = (pi) => {
	const extensionDir = dirname(fileURLToPath(import.meta.url));

	pi.on("model_select", (event, ctx) => {
		const warning = event.source !== "restore" && event.previousModel
			? cacheSwitchWarning(ctx, event.previousModel, event.model)
			: undefined;
		ctx.ui.setStatus(CACHE_STATUS_KEY, warning && `⚠ ${warning}`);
	});
	pi.on("turn_start", (_event, ctx) => {
		ctx.ui.setStatus(CACHE_STATUS_KEY, undefined);
	});

	pi.registerTool({
		name: "switch_model",
		label: "Switch Model",
		description:
			"Show the current model, list/search models, or switch models. Supports aliases defined in aliases.json (e.g. 'cheap', 'coding'). Use when the user mentions a model by name, asks to identify or change the model, or when you need a model with different capabilities (reasoning, vision, cost, context window).",
		promptSnippet:
			"Use this tool when the user asks to identify, list, search, or switch models, requests a specific model/provider, or asks for cheaper/faster/vision/reasoning-capable models. Prefer action='search' before action='switch' when intent is ambiguous. Switching mid-conversation re-bills the full context on the new model, so only switch when the user asks or the benefit is clear.",
		parameters: Type.Object({
			action: StringEnum(["current", "list", "search", "switch"] as const, {
				description: "Action to perform: 'current' (show the active model), 'list' (show all models), 'search' (filter by query), or 'switch' (change model)",
			}),
			search: Type.Optional(
				Type.String({
					description:
						"For search/switch actions: search term to match model by provider, id, or name (e.g. 'sonnet', 'opus', 'gpt-5.2', 'anthropic/claude')",
				}),
			),
			provider: Type.Optional(
				Type.String({
					description: "Filter to a specific provider (e.g. 'anthropic', 'openai', 'google', 'openrouter')",
				}),
			),
			thinkingLevel: Type.Optional(
				StringEnum(THINKING_LEVELS, {
					description: "Thinking level to apply after switching. Pi clamps unsupported levels to the model's capabilities.",
				}),
			),
		}),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			let models = ctx.modelRegistry.getAvailable();
			const currentModel = ctx.model;
			const provider = params.provider?.trim() ?? "";
			const normalizedProvider = provider.toLowerCase();
			const search = params.search?.trim() ?? "";
			const normalizedSearch = search.toLowerCase();

			if (params.action === "current") {
				if (!currentModel) {
					throw new Error("No model is currently active");
				}

				return {
					content: [
						{
							type: "text",
							text: `Current model: ${currentModel.provider}/${currentModel.id} (${currentModel.name}), thinking: ${pi.getThinkingLevel()}`,
						},
					],
					details: undefined,
				};
			}

			const { aliases, source: aliasSource, error: aliasLoadError } = loadAliases(ctx.cwd, extensionDir);
			const aliasWarning = aliasLoadError ? `\n\nWarning: ${aliasLoadError}` : "";

			if (normalizedProvider) {
				models = models.filter((model) => model.provider.toLowerCase() === normalizedProvider);
				if (models.length === 0) {
					throw new Error(
						`No models available for provider "${provider}". Available providers: ${[...new Set(ctx.modelRegistry.getAvailable().map((model) => model.provider))].join(", ")}`,
					);
				}
			}

			if (params.action === "list") {
				if (models.length === 0) {
					return {
						content: [
							{
								type: "text",
								text: "No models available. Configure API keys for providers you want to use (see `pi --help` or check ~/.pi/agent/auth.json).",
							},
						],
						details: undefined,
					};
				}

				const aliasInfo = aliasLoadError
					? `\n\nWarning: ${aliasLoadError}`
					: Object.keys(aliases).length > 0
						? `\n\nAliases: ${Object.keys(aliases).join(", ")}${aliasSource ? ` (from ${aliasSource})` : ""}`
						: aliasSource
							? `\n\nAliases: (none) (from ${aliasSource})`
							: "";
				const lines = models.map((model) => formatModelLine(model, currentModel));
				return {
					content: [{ type: "text", text: `Available models (${models.length}):${aliasInfo}\n\n${lines.join("\n\n")}` }],
					details: undefined,
				};
			}

			if (params.action === "search") {
				if (!search) {
					throw new Error("search parameter required for search action");
				}

				const matches = models.filter(
					(model) =>
						model.id.toLowerCase().includes(normalizedSearch)
						|| model.name.toLowerCase().includes(normalizedSearch)
						|| model.provider.toLowerCase().includes(normalizedSearch),
				);
				if (matches.length === 0) {
					return {
						content: [{ type: "text", text: `No models found matching "${search}"` }],
						details: undefined,
					};
				}

				const lines = matches.map((model) => formatModelLine(model, currentModel));
				return {
					content: [{ type: "text", text: `Models matching "${search}" (${matches.length}):\n\n${lines.join("\n\n")}` }],
					details: undefined,
				};
			}

			if (!search) {
				throw new Error("search parameter required for switch action");
			}

			const activateModel = async (
				model: (typeof models)[number],
				requestedThinking: ThinkingLevel | undefined,
			): Promise<{ changedModel: boolean; thinkingText: string; cacheNote: string } | null> => {
				const changedModel = !currentModel || model.provider !== currentModel.provider || model.id !== currentModel.id;
				const cacheWarning = changedModel && currentModel ? cacheSwitchWarning(ctx, currentModel, model) : undefined;
				if (changedModel && !(await pi.setModel(model))) {
					return null;
				}
				const cacheNote = cacheWarning ? `\n\nNote: ${cacheWarning}.` : "";

				if (requestedThinking === undefined) {
					return { changedModel, thinkingText: "", cacheNote };
				}

				pi.setThinkingLevel(requestedThinking);
				const effectiveThinking = pi.getThinkingLevel();
				const requestedText = effectiveThinking === requestedThinking ? "" : ` (requested ${requestedThinking})`;
				return { changedModel, thinkingText: `, thinking: ${effectiveThinking}${requestedText}`, cacheNote };
			};

			const aliasKey = Object.keys(aliases).find((key) => key.toLowerCase() === normalizedSearch);
			if (aliasKey) {
				const aliasValue = aliases[aliasKey];
				const candidates = Array.isArray(aliasValue) ? aliasValue : [aliasValue];

				for (const candidate of candidates) {
					const [provider, ...idParts] = candidate.model.split("/");
					const id = idParts.join("/");
					const aliasMatch = models.find(
						(model) => model.provider.toLowerCase() === provider.toLowerCase() && model.id.toLowerCase() === id.toLowerCase(),
					);
					if (!aliasMatch) {
						continue;
					}

					const requestedThinking = params.thinkingLevel ?? candidate.thinkingLevel;
					const activation = await activateModel(aliasMatch, requestedThinking);
					if (!activation) {
						continue;
					}
					const actionText = activation.changedModel
						? `Switched to ${aliasMatch.provider}/${aliasMatch.id} (${aliasMatch.name}) via alias "${aliasKey}"`
						: `Already using ${aliasMatch.provider}/${aliasMatch.id}${requestedThinking === undefined ? "" : ` via alias "${aliasKey}"`}`;

					return {
						content: [{ type: "text", text: `${actionText}${activation.thinkingText}${activation.cacheNote}` }],
						details: undefined,
					};
				}

				throw new Error(`No available models found for alias "${aliasKey}". Tried: ${candidates.map((candidate) => candidate.model).join(", ")}`);
			}

			let match = models.find((model) => `${model.provider}/${model.id}`.toLowerCase() === normalizedSearch);
			if (!match) {
				match = models.find((model) => model.id.toLowerCase() === normalizedSearch);
			}

			if (!match) {
				const candidateModels = models.filter(
					(model) =>
						model.id.toLowerCase().includes(normalizedSearch)
						|| model.name.toLowerCase().includes(normalizedSearch)
						|| model.provider.toLowerCase().includes(normalizedSearch),
				);
				if (candidateModels.length === 1) {
					match = candidateModels[0];
				} else if (candidateModels.length > 1) {
					const list = candidateModels.map((model) => `  ${model.provider}/${model.id}`).join("\n");
					throw new Error(`Multiple models match "${search}":\n${list}\n\nBe more specific.${aliasWarning}`);
				}
			}

			if (!match) {
				throw new Error(`No model found matching "${search}"${aliasWarning}`);
			}

			const activation = await activateModel(match, params.thinkingLevel);
			if (!activation) {
				throw new Error(`Failed to switch to ${match.provider}/${match.id}`);
			}
			const actionText = activation.changedModel
				? `Switched to ${match.provider}/${match.id} (${match.name})`
				: `Already using ${match.provider}/${match.id}`;

			return {
				content: [{ type: "text", text: `${actionText}${activation.thinkingText}${activation.cacheNote}` }],
				details: undefined,
			};
		},
	});
};

export default extension;
